    CONSTRAINT agent_steps_step_type_check CHECK (((step_type)::text = ANY ((ARRAY['start'::character varying, 'task'::character varying, 'approval'::character varying, 'gateway'::character varying, 'notification'::character varying, 'end'::character varying])::text[])))
);


