--
-- Name: grc_ownership_matrix; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.grc_ownership_matrix AS
 SELECT 'control'::text AS entity_type,
    co.control_id AS entity_id,
    co.user_id,
    co.ownership_type,
    co.is_primary,
    c.owner_team_id AS primary_team_id,
    c.secondary_owner_team_id AS secondary_team_id,
    c.owner_dept_id AS dept_id,
    t.team_code,
    t.name_en AS team_name,
    d.name_en AS dept_name,
    gra.raci_role
   FROM ((((__TENANT_SCHEMA__.control_owners co
     LEFT JOIN __TENANT_SCHEMA__.controls c ON (((c.control_id)::text = (co.control_id)::text)))
     LEFT JOIN __TENANT_SCHEMA__.teams t ON ((t.team_id = c.owner_team_id)))
     LEFT JOIN __TENANT_SCHEMA__.departments d ON ((d.dept_id = c.owner_dept_id)))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra ON ((((gra.entity_type)::text = 'control'::text) AND ((gra.entity_id)::text = (co.control_id)::text) AND ((gra.user_id)::text = (co.user_id)::text) AND (gra.is_active = true) AND (gra.deleted_at IS NULL))))
  WHERE (co.deleted_at IS NULL)
UNION ALL
 SELECT 'risk'::text AS entity_type,
    ro.risk_id AS entity_id,
    ro.user_id,
    ro.ownership_type,
    ro.is_primary,
    r.owner_team_id AS primary_team_id,
    r.secondary_owner_team_id AS secondary_team_id,
    r.owner_dept_id AS dept_id,
    t.team_code,
    t.name_en AS team_name,
    d.name_en AS dept_name,
    gra.raci_role
   FROM ((((__TENANT_SCHEMA__.risk_owners ro
     LEFT JOIN __TENANT_SCHEMA__.risks r ON (((r.risk_id)::text = (ro.risk_id)::text)))
     LEFT JOIN __TENANT_SCHEMA__.teams t ON ((t.team_id = r.owner_team_id)))
     LEFT JOIN __TENANT_SCHEMA__.departments d ON ((d.dept_id = r.owner_dept_id)))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra ON ((((gra.entity_type)::text = 'risk'::text) AND ((gra.entity_id)::text = (ro.risk_id)::text) AND ((gra.user_id)::text = (ro.user_id)::text) AND (gra.is_active = true) AND (gra.deleted_at IS NULL))))
  WHERE (ro.deleted_at IS NULL)
UNION ALL
 SELECT 'evidence'::text AS entity_type,
    (eo.evidence_id)::text AS entity_id,
    eo.user_id,
    eo.ownership_type,
    eo.is_primary,
    e.owner_team_id AS primary_team_id,
    e.secondary_owner_team_id AS secondary_team_id,
    e.owner_dept_id AS dept_id,
    t.team_code,
    t.name_en AS team_name,
    d.name_en AS dept_name,
    gra.raci_role
   FROM ((((__TENANT_SCHEMA__.evidence_owners eo
     LEFT JOIN __TENANT_SCHEMA__.evidence e ON ((e.evidence_id = eo.evidence_id)))
     LEFT JOIN __TENANT_SCHEMA__.teams t ON ((t.team_id = e.owner_team_id)))
     LEFT JOIN __TENANT_SCHEMA__.departments d ON ((d.dept_id = e.owner_dept_id)))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra ON ((((gra.entity_type)::text = 'evidence'::text) AND ((gra.entity_id)::text = (eo.evidence_id)::text) AND ((gra.user_id)::text = (eo.user_id)::text) AND (gra.is_active = true) AND (gra.deleted_at IS NULL))))
  WHERE (eo.deleted_at IS NULL);


