    CONSTRAINT grc_qiyas_control_feedback_test_result_check CHECK (((test_result)::text = ANY ((ARRAY['pass'::character varying, 'fail'::character varying, 'partial'::character varying, 'not_tested'::character varying])::text[])))
);


--
-- Name: grc_raci_gaps; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.grc_raci_gaps AS
 SELECT 'control'::text AS entity_type,
    c.control_id AS entity_id,
    c.title AS entity_name,
        CASE
            WHEN (co.owner_id IS NULL) THEN false
            ELSE true
        END AS has_user_owner,
        CASE
            WHEN (c.owner_team_id IS NULL) THEN false
            ELSE true
        END AS has_team_owner,
        CASE
            WHEN (c.owner_dept_id IS NULL) THEN false
            ELSE true
        END AS has_dept_owner,
        CASE
            WHEN (gra_r.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_responsible,
        CASE
            WHEN (gra_a.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_accountable
   FROM (((__TENANT_SCHEMA__.controls c
     LEFT JOIN __TENANT_SCHEMA__.control_owners co ON ((((co.control_id)::text = (c.control_id)::text) AND (co.is_primary = true) AND (co.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_r ON ((((gra_r.entity_type)::text = 'control'::text) AND ((gra_r.entity_id)::text = (c.control_id)::text) AND ((gra_r.raci_role)::text = 'responsible'::text) AND (gra_r.is_active = true) AND (gra_r.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_a ON ((((gra_a.entity_type)::text = 'control'::text) AND ((gra_a.entity_id)::text = (c.control_id)::text) AND ((gra_a.raci_role)::text = 'accountable'::text) AND (gra_a.is_active = true) AND (gra_a.deleted_at IS NULL))))
  WHERE (c.deleted_at IS NULL)
UNION ALL
 SELECT 'risk'::text AS entity_type,
    r.risk_id AS entity_id,
    r.title AS entity_name,
        CASE
            WHEN (ro.owner_id IS NULL) THEN false
            ELSE true
        END AS has_user_owner,
        CASE
            WHEN (r.owner_team_id IS NULL) THEN false
            ELSE true
        END AS has_team_owner,
        CASE
            WHEN (r.owner_dept_id IS NULL) THEN false
            ELSE true
        END AS has_dept_owner,
        CASE
            WHEN (gra_r.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_responsible,
        CASE
            WHEN (gra_a.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_accountable
   FROM (((__TENANT_SCHEMA__.risks r
     LEFT JOIN __TENANT_SCHEMA__.risk_owners ro ON ((((ro.risk_id)::text = (r.risk_id)::text) AND (ro.is_primary = true) AND (ro.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_r ON ((((gra_r.entity_type)::text = 'risk'::text) AND ((gra_r.entity_id)::text = (r.risk_id)::text) AND ((gra_r.raci_role)::text = 'responsible'::text) AND (gra_r.is_active = true) AND (gra_r.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_a ON ((((gra_a.entity_type)::text = 'risk'::text) AND ((gra_a.entity_id)::text = (r.risk_id)::text) AND ((gra_a.raci_role)::text = 'accountable'::text) AND (gra_a.is_active = true) AND (gra_a.deleted_at IS NULL))))
  WHERE (r.deleted_at IS NULL)
UNION ALL
 SELECT 'evidence'::text AS entity_type,
    (e.evidence_id)::text AS entity_id,
    e.title AS entity_name,
        CASE
            WHEN (eo.owner_id IS NULL) THEN false
            ELSE true
        END AS has_user_owner,
        CASE
            WHEN (e.owner_team_id IS NULL) THEN false
            ELSE true
        END AS has_team_owner,
        CASE
            WHEN (e.owner_dept_id IS NULL) THEN false
            ELSE true
        END AS has_dept_owner,
        CASE
            WHEN (gra_r.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_responsible,
        CASE
            WHEN (gra_a.assignment_id IS NULL) THEN false
            ELSE true
        END AS has_accountable
   FROM (((__TENANT_SCHEMA__.evidence e
     LEFT JOIN __TENANT_SCHEMA__.evidence_owners eo ON (((eo.evidence_id = e.evidence_id) AND (eo.is_primary = true) AND (eo.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_r ON ((((gra_r.entity_type)::text = 'evidence'::text) AND ((gra_r.entity_id)::text = (e.evidence_id)::text) AND ((gra_r.raci_role)::text = 'responsible'::text) AND (gra_r.is_active = true) AND (gra_r.deleted_at IS NULL))))
     LEFT JOIN __TENANT_SCHEMA__.grc_raci_assignments gra_a ON ((((gra_a.entity_type)::text = 'evidence'::text) AND ((gra_a.entity_id)::text = (e.evidence_id)::text) AND ((gra_a.raci_role)::text = 'accountable'::text) AND (gra_a.is_active = true) AND (gra_a.deleted_at IS NULL))))
  WHERE (e.deleted_at IS NULL);


