--
-- Name: v_bcp_dashboard_summary; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_bcp_dashboard_summary AS
 SELECT (count(*))::integer AS total_plans,
    (count(*) FILTER (WHERE ((bcp_plans.status)::text = 'approved'::text)))::integer AS approved_count,
    (count(*) FILTER (WHERE ((bcp_plans.status)::text = 'draft'::text)))::integer AS draft_count,
    (count(*) FILTER (WHERE ((bcp_plans.status)::text = 'active'::text)))::integer AS active_count,
    (count(*) FILTER (WHERE ((bcp_plans.status)::text = 'review_required'::text)))::integer AS review_required_count,
    (count(*) FILTER (WHERE ((bcp_plans.last_exercise_at IS NULL) OR (bcp_plans.last_exercise_at < (now() - '180 days'::interval)))))::integer AS untested_count,
    ( SELECT (count(*))::integer AS count
           FROM __TENANT_SCHEMA__.bia_assessments
          WHERE (bia_assessments.deleted_at IS NULL)) AS total_bias,
    ( SELECT (count(*))::integer AS count
           FROM __TENANT_SCHEMA__.bcp_exercises
          WHERE (bcp_exercises.deleted_at IS NULL)) AS total_exercises
   FROM __TENANT_SCHEMA__.bcp_plans
  WHERE (bcp_plans.deleted_at IS NULL);


--
-- Name: v_enterprise_user_delegated_permissions; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_enterprise_user_delegated_permissions AS
 SELECT DISTINCT d.to_user_id AS user_id,
    p.code AS permission_code,
    p.module_code,
    p.resource_code,
    p.action_code,
    d.scope_type,
    d.scope_id,
    ura.authority_level,
    ura.functional_role_code,
    d.from_user_id AS delegated_from
   FROM ((((__TENANT_SCHEMA__.delegations d
     JOIN __TENANT_SCHEMA__.enterprise_user_role_assignments ura ON ((((ura.user_id)::text = (d.from_user_id)::text) AND ((d.functional_role_code IS NULL) OR (ura.functional_role_code = d.functional_role_code)) AND ((d.module_code IS NULL) OR (ura.module_code = d.module_code)))))
     JOIN __TENANT_SCHEMA__.functional_roles fr ON ((fr.code = ura.functional_role_code)))
     JOIN __TENANT_SCHEMA__.role_permissions rp ON ((rp.functional_role_id = fr.id)))
     JOIN __TENANT_SCHEMA__.permissions p ON ((p.id = rp.permission_id)))
  WHERE ((d.is_active = true) AND (ura.is_active = true) AND (d.valid_from <= now()) AND (d.valid_to > now()) AND ((ura.valid_to IS NULL) OR (ura.valid_to > now())));


--
-- Name: v_enterprise_user_permissions; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_enterprise_user_permissions AS
 SELECT DISTINCT ura.user_id,
    p.code AS permission_code,
    p.module_code,
    p.resource_code,
    p.action_code,
    ura.scope_type,
    ura.scope_id,
    ura.authority_level,
    ura.functional_role_code
   FROM (((__TENANT_SCHEMA__.enterprise_user_role_assignments ura
     JOIN __TENANT_SCHEMA__.functional_roles fr ON ((fr.code = ura.functional_role_code)))
     JOIN __TENANT_SCHEMA__.role_permissions rp ON ((rp.functional_role_id = fr.id)))
     JOIN __TENANT_SCHEMA__.permissions p ON ((p.id = rp.permission_id)))
  WHERE ((ura.is_active = true) AND ((ura.valid_to IS NULL) OR (ura.valid_to > now())));


--
-- Name: v_training_regulatory_coverage; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_training_regulatory_coverage AS
 SELECT ctm.framework_code,
    tc.content_id,
    tc.code AS content_code,
    tc.title,
    tc.title_ar,
    tc.category,
    tc.is_mandatory,
    tc.duration_minutes,
    tc.recertification_days,
    ctm.mapping_type,
    ctm.coverage_pct,
    count(DISTINCT ctm.control_code) AS controls_covered
   FROM (__TENANT_SCHEMA__.control_training_mappings ctm
     JOIN __TENANT_SCHEMA__.training_content tc ON (((tc.content_id = ctm.content_id) AND (tc.deleted_at IS NULL) AND (tc.is_active = true))))
  WHERE ((ctm.deleted_at IS NULL) AND (ctm.is_active = true))
  GROUP BY ctm.framework_code, tc.content_id, tc.code, tc.title, tc.title_ar, tc.category, tc.is_mandatory, tc.duration_minutes, tc.recertification_days, ctm.mapping_type, ctm.coverage_pct;


--
-- Name: v_user_role_responsibility_matrix; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_user_role_responsibility_matrix AS
 SELECT ura.user_id,
    u.email,
    u.name,
    ura.role_id,
    rf.function_code,
    rf.name_en AS function_name_en,
    rf.name_ar AS function_name_ar,
    rfm.can_author,
    rfm.can_approve,
    rfm.is_responsible,
    rfm.is_accountable,
    rfm.is_consulted,
    rfm.is_informed,
    COALESCE(rfsm.scope_type, 'global'::character varying) AS scope_type,
    rfsm.scope_id,
    ura.is_primary,
    ura.active
   FROM ((((__TENANT_SCHEMA__.user_role_assignments ura
     LEFT JOIN public.users u ON (((u.user_id)::text = (ura.user_id)::text)))
     JOIN __TENANT_SCHEMA__.role_function_map rfm ON (((rfm.role_id = ura.role_id) AND (rfm.enabled = true))))
     JOIN __TENANT_SCHEMA__.role_functions rf ON (((rf.function_code)::text = (rfm.function_code)::text)))
     LEFT JOIN __TENANT_SCHEMA__.role_function_scope_map rfsm ON (((rfsm.role_id = rfm.role_id) AND ((rfsm.function_code)::text = (rfm.function_code)::text) AND (rfsm.enabled = true))))
  WHERE ((ura.active = true) AND ((ura.valid_to IS NULL) OR (ura.valid_to > now())));


