--
-- Name: v_vendor_dashboard_summary; Type: VIEW; Schema: __TENANT_SCHEMA__; Owner: -
--

CREATE VIEW __TENANT_SCHEMA__.v_vendor_dashboard_summary AS
 SELECT (count(*))::integer AS total_vendors,
    (count(*) FILTER (WHERE ((vendors.status)::text = 'active'::text)))::integer AS active_count,
    (count(*) FILTER (WHERE ((vendors.risk_tier)::text = ANY ((ARRAY['critical'::character varying, 'high'::character varying])::text[]))))::integer AS high_risk_count,
    (count(*) FILTER (WHERE ((vendors.status)::text = 'pending_review'::text)))::integer AS pending_review_count,
    (count(*) FILTER (WHERE ((vendors.dd_status)::text = 'expired'::text)))::integer AS dd_expired_count,
    (count(*) FILTER (WHERE ((vendors.contract_expiry < (now() + '90 days'::interval)) AND (vendors.contract_expiry IS NOT NULL))))::integer AS contract_expiring_count,
    ( SELECT (count(*))::integer AS count
           FROM __TENANT_SCHEMA__.vendor_sla_breach_log
          WHERE ((vendor_sla_breach_log.remediation_status)::text = ANY ((ARRAY['open'::character varying, 'investigating'::character varying])::text[]))) AS open_sla_breaches
   FROM __TENANT_SCHEMA__.vendors
  WHERE (vendors.deleted_at IS NULL);


